	(52, 'TKT-7ZWV6VMQ-1761601801', 'EMP001', 'I want to talk to a real person', 'Resolved', 1, 'medium', '2025-10-27 13:50:01', NULL, NULL, NULL, NULL, 0, '2025-10-27 15:10:14', 'General', 'Escalated from Chatbot', 0),
