	(55, 'TKT-D3CPZ2OT-1761610436', 'HR001', 'yes', 'Resolved', 1, 'medium', '2025-10-27 16:13:57', NULL, NULL, NULL, '2025-12-01 18:05:11', 0, '2025-12-01 18:05:11', 'General', 'EMERGENCY: User chose escalation after 3 retries', 0),
