	(57, 'TKT-EGWBRVRI-1761611750', 'Emp002', '<?php  namespace App\\Http\\Controllers;  use Illuminate\\Http\\Request; use App\\Models\\Query; use App\\Models\\HrInbox; use App\\Models\\GuidedQuestion; use Illuminate\\Support\\Str; use App\\Services\\DialogflowService; use Illuminate\\Support\\Facades\\Auth; use Illuminate\\Support\\Facades\\Log; use Illuminate\\Support\\Facades\\Session; use Illuminate\\Support\\Facades\\DB;  class DialogflowController extends Controller {     private $maxRetries = 3;      public function webhook(Request $request)     {         try {             Log::info(\'ðŸ” Dialogflow Webhook Called\', [\'input\' => $request->all()]);              // ðŸ†• FIXED: Handle multiple input formats             $queryText = $this->extractQueryText($request);             $employeeNum = Auth::check() ? Auth::user()->employeeNum : 0;              if (empty($queryText)) {                 Log::warning(\'Empty query text received\');                 return response()->json([                     \'status\' => \'success\',                     \'fulfillmentText\' => "I didn\'t receive your message. Could you please try again?"                 ]);             }              Log::info(\'Processing query:\', [\'query\' => $queryText, \'employee\' => $employeeNum]);              // ðŸ†• NEW: Check if this is a retry after multiple failed attempts             $retryResponse = $this->handleRetryScenario($queryText, $employeeNum);             if ($retryResponse) {                 return $retryResponse;             }              // ðŸ’¬ Handle greetings - start guided flow immediately             if ($this->isGreeting($queryText)) {                 Log::info(\'Greeting detected, starting guided flow\');                 // ðŸ†• Reset retry counter for new conversation                 $this->resetRetryCount();                 return response()->json([                     \'status\' => \'guided_flow\',                     \'fulfillmentText\' => "ðŸ‘‹ Hello! I\'m here to help with HR questions. Let me guide you to the right information.",                     \'guided_flow\' => true                 ]);             }              // ðŸ”¥ IMPROVED: Handle explicit escalation requests             if ($this->isEscalationRequest($queryText)) {                 Log::info(\'Escalation request detected\', [\'query\' => $queryText]);                 $this->resetRetryCount();                 return $this->escalateToHR($queryText, $employeeNum, \'User requested human assistance\');             }              // ðŸ’¬ Handle simple conversational responses             $conversationalResponse = $this->handleConversationalQueries($queryText);             if ($conversationalResponse) {                 $this->resetRetryCount();                 return $conversationalResponse;             }              // ðŸŽ¯ Try Dialogflow for direct questions             $sessionId = session()->getId() ?? Str::random(10);             $dialogflow = new DialogflowService();                          Log::info(\'Calling Dialogflow service\', [\'sessionId\' => $sessionId]);             $result = $dialogflow->detectIntent($queryText, $sessionId);             $dialogflow->close();              $confidence = $result->getIntentDetectionConfidence() ?? 0.0;             $fulfillmentText = $result->getFulfillmentText() ?? "I want to make sure I give you accurate information. Let me guide you through our topics.";             $intentName = $result->getIntent() ? $result->getIntent()->getDisplayName() : \'Default Fallback Intent\';              Log::info(\'Dialogflow Response\', [                 \'confidence\' => $confidence,                 \'intent\' => $intentName,                 \'fulfillmentText\' => $fulfillmentText             ]);              // ðŸ†• NEW: Check if this is HR-related but bot can\'t answer properly             $isHRRelated = $this->isHRRelatedQuestion($queryText);             $cantAnswer = $this->cantAnswerQuestion($confidence, $intentName, $fulfillmentText);              if ($isHRRelated && $cantAnswer) {                 Log::info(\'HR-related question detected but bot cannot answer\', [                     \'confidence\' => $confidence,                     \'intent\' => $intentName                 ]);                 return $this->suggestHREscalation($queryText, $employeeNum, "HR-related question with low confidence");             }              // ðŸ”¥ IMPROVED: Auto-escalate based on multiple factors             if ($this->shouldEscalate($queryText, $confidence, $intentName)) {                 Log::info(\'Auto-escalating query\', [                     \'reason\' => \'Low confidence or urgent content\',                     \'confidence\' => $confidence,                     \'intent\' => $intentName                 ]);                 $this->resetRetryCount();                 return $this->escalateToHR($queryText, $employeeNum, "Auto-escalated: Confidence {$confidence}, Intent: {$intentName}");             }              // ðŸ†• NEW: Handle retry logic for unclear questions             if ($this->shouldRetry($confidence, $intentName)) {                 $retryCount = $this->incrementRetryCount();                 Log::info(\'Low confidence response, prompting retry\', [                     \'retryCount\' => $retryCount,                     \'confidence\' => $confidence                 ]);                  if ($retryCount >= $this->maxRetries) {                     return $this->offerHREscalation($queryText, $employeeNum);                 }                  return response()->json([                     \'status\' => \'retry\',                     \'fulfillmentText\' => $this->getRetryMessage($retryCount),                     \'retryCount\' => $retryCount,                     \'needs_clarification\' => true                 ]);             }              // ðŸ¤– If reasonable confidence, return direct answer             if ($confidence > 0.6 || $intentName !== \'Default Fallback Intent\') {                 Log::info(\'Returning direct answer\', [\'confidence\' => $confidence, \'intent\' => $intentName]);                 $this->resetRetryCount();                  Query::create([                     \'queryID\' => Str::uuid(),                     \'employeeNum\' => $employeeNum,                     \'question\' => $queryText,                     \'response\' => $fulfillmentText,                     \'confidenceScore\' => $confidence,                     \'queryType\' => \'Dialogflow\',                     \'questionTime\' => now(),                     \'responseTime\' => now(),                     \'isEscalated\' => false,                     \'handledBy\' => \'Bot\',                 ]);                  return response()->json([                     \'status\' => \'success\',                     \'fulfillmentText\' => $fulfillmentText,                     \'confidence\' => $confidence,                     \'intent\' => $intentName                 ]);             }              // ðŸ”„ Low confidence - start guided flow             Log::info(\'Low confidence, starting guided flow\', [\'confidence\' => $confidence]);             $this->resetRetryCount();             return response()->json([                 \'status\' => \'guided_flow\',                 \'fulfillmentText\' => "I want to make sure I give you the right information. Let me guide you through our HR topics.",                 \'guided_flow\' => true             ]);          } catch (\\Throwable $e) {             Log::error(\'âŒ Dialogflow error: \' . $e->getMessage(), [                 \'trace\' => $e->getTraceAsString(),                 \'request\' => $request->all()             ]);              // ðŸ†• FIXED: Better error response that doesn\'t break the frontend             return response()->json([                 \'status\' => \'success\', // Use success to prevent frontend errors                 \'fulfillmentText\' => "I\'m having trouble processing your request right now. Let me guide you through our HR topics instead.",                 \'fallback\' => true             ]);         }     }      /**      * ðŸ†• NEW: Check if question is HR-related      */     private function isHRRelatedQuestion(string $queryText): bool     {         $hrKeywords = [             // Employment             \'hire\', \'hiring\', \'recruitment\', \'recruit\', \'job\', \'position\', \'role\',             \'interview\', \'application\', \'resume\', \'cv\', \'candidate\',             \'onboarding\', \'orientation\', \'probation\', \'contract\',                          // Compensation & Benefits             \'salary\', \'pay\', \'wage\', \'compensation\', \'benefit\', \'insurance\',             \'health insurance\', \'dental\', \'vision\', \'retirement\', \'pension\',             \'401k\', \'bonus\', \'commission\', \'raise\', \'increase\', \'promotion\',                          // Time Off             \'vacation\', \'holiday\', \'leave\', \'sick\', \'time off\', \'pto\',             \'personal day\', \'maternity\', \'paternity\', \'fmla\',                          // Policies             \'policy\', \'procedure\', \'handbook\', \'rule\', \'regulation\',             \'code of conduct\', \'dress code\', \'attendance\', \'punctuality\',                          // Performance             \'performance\', \'review\', \'appraisal\', \'evaluation\', \'kpi\',             \'goal\', \'objective\', \'feedback\', \'development\', \'training\',                          // Employee Relations             \'grievance\', \'complaint\', \'concern\', \'issue\', \'problem\',             \'dispute\', \'conflict\', \'mediation\', \'disciplinary\', \'warning\',                          // Workplace             \'workplace\', \'environment\', \'safety\', \'harassment\', \'discrimination\',             \'diversity\', \'inclusion\', \'accommodation\', \'remote\', \'hybrid\',                          // Separation             \'termination\', \'fired\', \'dismissal\', \'resignation\', \'quit\',             \'exit\', \'severance\', \'layoff\', \'redundancy\'         ];          foreach ($hrKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Check if bot cannot answer the question properly      */     private function cantAnswerQuestion(float $confidence, string $intentName, string $fulfillmentText): bool     {         // Low confidence         if ($confidence < 0.4) {             return true;         }          // Default fallback intent         if ($intentName === \'Default Fallback Intent\') {             return true;         }          // Generic or unclear responses         $unclearResponses = [             \'i didn\\\'t understand\',             \'can you rephrase\',             \'could you clarify\',             \'i\\\'m not sure\',             \'can you try asking\',             \'please rephrase\',             \'not clear\'         ];          foreach ($unclearResponses as $unclear) {             if (stripos($fulfillmentText, $unclear) !== false) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Suggest HR escalation for HR-related questions bot can\'t answer      */     private function suggestHREscalation(string $queryText, $employeeNum, string $reason): \\Illuminate\\Http\\JsonResponse     {         Log::info(\'Suggesting HR escalation\', [\'reason\' => $reason]);          return response()->json([             \'status\' => \'suggest_escalation\',             \'fulfillmentText\' => "I understand this is an HR-related question, but I want to make sure you get the most accurate information. Would you like me to escalate this to our HR team for proper assistance?",             \'suggest_hr\' => true,             \'pending_escalation\' => [                 \'query\' => $queryText,                 \'employeeNum\' => $employeeNum,                 \'reason\' => $reason             ],             \'options\' => [                 [\'text\' => \'âœ… Yes, please escalate to HR\', \'action\' => \'escalate\'],                 [\'text\' => \'ðŸ”„ No, let me rephrase my question\', \'action\' => \'rephrase\']             ]         ]);     }      /**      * ðŸ†• NEW: Handle retry scenario (when user responds to retry prompt)      */     private function handleRetryScenario(string $queryText, $employeeNum): ?\\Illuminate\\Http\\JsonResponse     {         $retryCount = Session::get(\'retry_count\', 0);                  if ($retryCount > 0) {             // Check if user wants to escalate             if ($this->wantsEscalation($queryText)) {                 $this->resetRetryCount();                 return $this->escalateToHR($queryText, $employeeNum, "User chose escalation after {$retryCount} retries");             }              // Check if user wants to rephrase             if ($this->wantsToRephrase($queryText)) {                 $this->resetRetryCount();                 return response()->json([                     \'status\' => \'retry_reset\',                     \'fulfillmentText\' => "Okay, please ask your question in a different way and I\'ll do my best to help!"                 ]);             }         }          return null;     }      /**      * ðŸ†• NEW: Check if user wants escalation      */     private function wantsEscalation(string $queryText): bool     {         $escalationPatterns = [             \'/\\b(yes|yeah|sure|okay|please|escalate|hr)\\b/i\',             \'/\\bgo ahead\\b/i\',             \'/\\bcontact hr\\b/i\',             \'/\\bsend to hr\\b/i\',             \'/\\bhuman help\\b/i\'         ];          foreach ($escalationPatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Check if user wants to rephrase      */     private function wantsToRephrase(string $queryText): bool     {         $rephrasePatterns = [             \'/\\b(no|nope|nevermind)\\b/i\',             \'/\\brephrase\\b/i\',             \'/\\bdifferent\\b/i\',             \'/\\btry again\\b/i\',             \'/\\bnew question\\b/i\',             \'/\\bstart over\\b/i\'         ];          foreach ($rephrasePatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Check if we should retry (low confidence responses)      */     private function shouldRetry(float $confidence, string $intentName): bool     {         if ($confidence < 0.5) {             return true;         }          if ($intentName === \'Default Fallback Intent\') {             return true;         }          return false;     }      /**      * ðŸ†• NEW: Get appropriate retry message based on retry count      */     private function getRetryMessage(int $retryCount): string     {         $messages = [             1 => "I\'m not sure I understand. Could you please rephrase your question?",             2 => "I\'m still having trouble understanding. Could you try asking in a different way?",             3 => "I want to make sure I help you properly. Could you provide more details or context?"         ];          return $messages[$retryCount] ?? $messages[1];     }      /**      * ðŸ†• NEW: Offer HR escalation after max retries      */     private function offerHREscalation(string $queryText, $employeeNum): \\Illuminate\\Http\\JsonResponse     {         Log::info(\'Offering HR escalation after max retries\');          return response()->json([             \'status\' => \'offer_escalation\',             \'fulfillmentText\' => "I\'m having difficulty understanding your question after several attempts. Would you like me to escalate this to our HR team who can provide better assistance?",             \'max_retries_reached\' => true,             \'pending_escalation\' => [                 \'query\' => $queryText,                 \'employeeNum\' => $employeeNum,                 \'reason\' => \'Max retries reached\'             ],             \'options\' => [                 [\'text\' => \'âœ… Yes, please connect me with HR\', \'action\' => \'escalate\'],                 [\'text\' => \'ðŸ”„ Let me try asking differently\', \'action\' => \'rephrase\'],                 [\'text\' => \'âŒ Cancel and start over\', \'action\' => \'cancel\']             ]         ]);     }      /**      * ðŸ†• NEW: Increment retry count      */     private function incrementRetryCount(): int     {         $count = Session::get(\'retry_count\', 0) + 1;         Session::put(\'retry_count\', $count);         Session::put(\'last_retry_time\', now());         return $count;     }      /**      * ðŸ†• NEW: Reset retry count      */     private function resetRetryCount(): void     {         Session::forget(\'retry_count\');         Session::forget(\'last_retry_time\');     }      /**      * ðŸ†• FIXED: Extract query text from multiple possible input formats      */     private function extractQueryText(Request $request): string     {         // Format 1: Direct message parameter (from our frontend)         if ($request->has(\'message\')) {             return trim($request->input(\'message\'));         }          // Format 2: Dialogflow webhook format         if ($request->has(\'queryResult.queryText\')) {             return trim($request->input(\'queryResult.queryText\'));         }          // Format 3: Alternative Dialogflow format         if ($request->has(\'queryResult.parameters.message\')) {             return trim($request->input(\'queryResult.parameters.message\'));         }          // Format 4: Raw text in request         $text = $request->input(\'text\') ?? $request->input(\'query\') ?? \'\';         return trim($text);     }      /**      * ðŸ†• IMPROVED: Better greeting detection      */     private function isGreeting(string $queryText): bool     {         $greetingPatterns = [             \'/^(hi|hello|hey|greetings|good morning|good afternoon|good evening)[\\s\\.,!]*$/i\',             \'/^start$/i\',             \'/^help$/i\',             \'/^\\?$/\',             \'/^hello there$/i\',             \'/^hi there$/i\'         ];          foreach ($greetingPatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ”¥ IMPROVED: Better detection for escalation requests      */     private function isEscalationRequest(string $queryText): bool     {         $escalationPatterns = [             \'/\\b(escalate|human|real person|live agent|representative|manager)\\b/i\',             \'/\\btalk to (hr|human|person|someone|agent|manager)\\b/i\',             \'/\\bspeak with (hr|human|person|someone|agent|manager)\\b/i\',             \'/\\bconnect with (hr|human|person|someone|agent)\\b/i\',             \'/\\bI want to talk to\\b/i\',             \'/\\bI need to speak with\\b/i\',             \'/\\bcan I speak with\\b/i\',             \'/\\bcontact hr\\b/i\',             \'/\\bget me hr\\b/i\',             \'/\\bnot a bot\\b/i\',             \'/\\bnot chatbot\\b/i\',             \'/\\breal human\\b/i\',             \'/\\blive person\\b/i\',             \'/\\bhuman help\\b/i\'         ];          foreach ($escalationPatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Handle simple conversational queries without Dialogflow      */     private function handleConversationalQueries(string $queryText): ?\\Illuminate\\Http\\JsonResponse     {         $conversationalMap = [             \'thanks\' => ["You\'re very welcome! ðŸ˜Š Is there anything else I can help you with?", "Happy to help! Let me know if you need anything else."],             \'thank you\' => ["You\'re very welcome! ðŸ˜Š Is there anything else I can help you with?", "My pleasure! Feel free to ask if you have more questions."],             \'bye\' => ["ðŸ‘‹ Goodbye! Feel free to ask if you have more HR questions.", "Have a great day! ðŸ‘‹"],             \'goodbye\' => ["ðŸ‘‹ Goodbye! Feel free to ask if you have more HR questions.", "Take care! ðŸ‘‹"],             \'how are you\' => ["I\'m doing great, thanks for asking! Ready to help with your HR questions. ðŸ˜Š", "I\'m functioning well! How can I assist you with HR matters today?"],             \'who are you\' => ["I\'m Aihra, your AI HR Assistant! I\'m here to help with HR questions and guide you to the right information. ðŸ¤–", "I\'m Aihra, an AI assistant specialized in HR topics. How can I help you today?"],         ];          foreach ($conversationalMap as $pattern => $responses) {             if (stripos($queryText, $pattern) !== false) {                 $response = $responses[array_rand($responses)];                 return response()->json([                     \'status\' => \'success\',                     \'fulfillmentText\' => $response                 ]);             }         }          return null;     }      /**      * ðŸ”¥ IMPROVED: Better escalation logic      */     private function shouldEscalate(string $queryText, float $confidence, string $intentName): bool     {         // Always escalate if it\'s the default fallback intent with low confidence         if ($intentName === \'Default Fallback Intent\' && $confidence < 0.4) {             return true;         }          // Escalate if confidence is very low         if ($confidence < 0.3) {             return true;         }          // Escalate for urgent/emotional keywords         $urgentKeywords = [             \'urgent\', \'emergency\', \'complaint\', \'issue\', \'problem\', \'error\',             \'not working\', \'help me\', \'now\', \'asap\', \'immediately\', \'right now\',             \'serious\', \'critical\', \'angry\', \'frustrated\', \'disappointed\', \'upset\',             \'unhappy\', \'wrong\', \'broken\', \'fix\', \'resolve\', \'complaint\',             \'harassment\', \'discrimination\', \'bullying\', \'unsafe\', \'danger\'         ];          foreach ($urgentKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return true;             }         }          // Escalate complex personal issues         $personalIssues = [             \'salary\', \'pay\', \'raise\', \'promotion\', \'disciplinary\', \'warning\',             \'termination\', \'fired\', \'resign\', \'quit\', \'legal\', \'lawyer\',             \'contract\', \'agreement\', \'confidential\', \'private\', \'personal\'         ];          $personalCount = 0;         foreach ($personalIssues as $issue) {             if (stripos($queryText, $issue) !== false) {                 $personalCount++;             }         }          // If multiple personal issues mentioned, escalate         if ($personalCount >= 2) {             return true;         }          return false;     }      /**      * ðŸ”¥ FIXED: Escalate query to HR inbox - ALWAYS creates real ticket      */     private function escalateToHR(string $queryText, $employeeNum, string $reason = \'User requested\'): \\Illuminate\\Http\\JsonResponse     {         $ticketNo = null;                  try {             Log::info("ðŸŽ¯ Starting escalation process...", [                 \'reason\' => $reason,                 \'employee\' => $employeeNum,                 \'query\' => substr($queryText, 0, 100)             ]);              // Generate unique ticket number FIRST             $ticketNo = \'TKT-\' . strtoupper(Str::random(8)) . \'-\' . time();             Log::info("ðŸŽ¯ Generated ticket: " . $ticketNo);              // Determine priority based on content             $priority = $this->determinePriority($queryText);             $category = $this->determineCategory($queryText);              // ðŸ†• CRITICAL FIX: Create HR inbox ticket with multiple fallback attempts             $inbox = null;             $maxAttempts = 3;                          for ($attempt = 1; $attempt <= $maxAttempts; $attempt++) {                 try {                     $inbox = HrInbox::create([                         \'ticket_no\' => $ticketNo,                         \'from_user\' => $employeeNum ?: \'GUEST\',                         \'message\' => $queryText,                         \'status\' => \'Open\',                         \'priority\' => $priority,                         \'category\' => $category,                         \'intent\' => \'Escalated from Chatbot: \' . $reason,                         \'confidence\' => 0.0,                         \'created_at\' => now(),                         \'updated_at\' => now(),                     ]);                     Log::info("âœ… HR Inbox created successfully on attempt {$attempt}", [\'ticket_no\' => $ticketNo]);                     break; // Success, break out of retry loop                                      } catch (\\Exception $createError) {                     Log::warning("âŒ HR Inbox creation failed on attempt {$attempt}: " . $createError->getMessage());                                          if ($attempt === $maxAttempts) {                         // Last attempt failed, try alternative creation method                         $inbox = $this->createTicketAlternativeMethod($ticketNo, $employeeNum, $queryText, $priority, $category, $reason);                         if ($inbox) {                             Log::info("âœ… HR Inbox created via alternative method", [\'ticket_no\' => $ticketNo]);                             break;                         }                         throw new \\Exception("Failed to create HR ticket after {$maxAttempts} attempts: " . $createError->getMessage());                     }                                          // Wait briefly before retry                     usleep(500000); // 0.5 seconds                 }             }              // Create query record with proper error handling             try {                 Query::create([                     \'queryID\' => Str::uuid(),                     \'employeeNum\' => $employeeNum,                     \'question\' => $queryText,                     \'response\' => \'Escalated to HR - \' . $ticketNo,                     \'confidenceScore\' => 0.0,                     \'queryType\' => \'Escalated\',                     \'questionTime\' => now(),                     \'responseTime\' => now(),                     \'isEscalated\' => true,                     \'handledBy\' => \'HR\',                 ]);                 Log::info("âœ… Query record created successfully");             } catch (\\Exception $queryError) {                 Log::warning(\'Query record creation failed, but HR ticket was created\', [                     \'error\' => $queryError->getMessage(),                     \'ticket_no\' => $ticketNo                 ]);                 // Continue even if query record fails - the main ticket is what matters             }              Log::info("âœ… Escalation completed successfully", [\'ticket_no\' => $ticketNo]);              return response()->json([                 \'status\' => \'escalated\',                 \'fulfillmentText\' => "âœ… I\'ve escalated your query to our HR team. They\'ll get back to you soon. Your ticket number is: **{$ticketNo}**",                 \'ticket_no\' => $ticketNo,                 \'escalated\' => true,                 \'priority\' => $priority             ]);          } catch (\\Exception $e) {             Log::error(\'âŒ Escalation failed: \' . $e->getMessage(), [                 \'trace\' => $e->getTraceAsString(),                 \'query\' => $queryText             ]);              // ðŸ†• CRITICAL FIX: ALWAYS create a ticket, even if basic methods fail             $finalTicketNo = $this->ensureTicketCreation($ticketNo, $employeeNum, $queryText, $reason);                          return response()->json([                 \'status\' => \'escalated\',                 \'fulfillmentText\' => "âœ… I\'ve created a support ticket for you. Our HR team will contact you soon. Your ticket number is: **{$finalTicketNo}**",                 \'ticket_no\' => $finalTicketNo,                 \'escalated\' => true,                 \'fallback_created\' => true             ]);         }     }      /**      * ðŸ†• NEW: Determine ticket priority based on content      */     private function determinePriority(string $queryText): string     {         $highPriorityKeywords = [             \'emergency\', \'urgent\', \'critical\', \'asap\', \'immediately\', \'now\',             \'harassment\', \'discrimination\', \'bullying\', \'unsafe\', \'danger\',             \'fired\', \'termination\', \'legal\', \'lawyer\', \'police\'         ];          $mediumPriorityKeywords = [             \'complaint\', \'issue\', \'problem\', \'error\', \'not working\', \'broken\',             \'salary\', \'pay\', \'raise\', \'promotion\', \'disciplinary\', \'warning\'         ];          foreach ($highPriorityKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return \'High\';             }         }          foreach ($mediumPriorityKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return \'Medium\';             }         }          return \'Low\';     }      /**      * ðŸ†• NEW: Determine ticket category based on content      */     private function determineCategory(string $queryText): string     {         $categories = [             \'Benefits\' => [\'benefit\', \'insurance\', \'health\', \'dental\', \'vacation\', \'time off\', \'leave\'],             \'Payroll\' => [\'salary\', \'pay\', \'paycheck\', \'wage\', \'bonus\', \'tax\'],             \'Employment\' => [\'hire\', \'hiring\', \'promotion\', \'raise\', \'position\', \'job\'],             \'Complaint\' => [\'complaint\', \'issue\', \'problem\', \'harassment\', \'discrimination\'],             \'Technical\' => [\'system\', \'login\', \'password\', \'access\', \'technical\', \'error\'],             \'Policy\' => [\'policy\', \'rule\', \'regulation\', \'procedure\', \'guideline\'],             \'General\' => [] // Default         ];          foreach ($categories as $category => $keywords) {             foreach ($keywords as $keyword) {                 if (stripos($queryText, $keyword) !== false) {                     return $category;                 }             }         }          return \'General\';     }      /**      * ðŸ†• NEW: Alternative ticket creation method using DB facade      */     private function createTicketAlternativeMethod(string $ticketNo, $employeeNum, string $queryText, string $priority, string $category, string $reason)     {         try {             Log::info("ðŸ”„ Trying alternative ticket creation method", [\'ticket_no\' => $ticketNo]);                          // Use DB facade for direct insertion             $now = now();             $result = DB::table(\'hr_inboxes\')->insert([                 \'ticket_no\' => $ticketNo,                 \'from_user\' => $employeeNum ?: \'GUEST\',                 \'message\' => $queryText,                 \'status\' => \'Open\',                 \'priority\' => $priority,                 \'category\' => $category,                 \'intent\' => \'Escalated from Chatbot: \' . $reason,                 \'confidence\' => 0.0,                 \'created_at\' => $now,                 \'updated_at\' => $now,             ]);              if ($result) {                 return DB::table(\'hr_inboxes\')->where(\'ticket_no\', $ticketNo)->first();             }                          return null;                      } catch (\\Exception $e) {             Log::error(\'Alternative ticket creation failed: \' . $e->getMessage());             return null;         }     }      /**      * ðŸ†• NEW: Ensure ticket creation no matter what - final fallback      */     private function ensureTicketCreation(?string $originalTicketNo, $employeeNum, string $queryText, string $reason): string     {         $ticketNo = $originalTicketNo ?: \'TKT-EMERGENCY-\' . time();                  try {             Log::info("ðŸš¨ EMERGENCY: Ensuring ticket creation with final fallback", [\'ticket_no\' => $ticketNo]);              // Try multiple creation methods             $methods = [                 \'eloquent_create\' => function() use ($ticketNo, $employeeNum, $queryText, $reason) {                     return HrInbox::create([                         \'ticket_no\' => $ticketNo,                         \'from_user\' => $employeeNum ?: \'GUEST\',                         \'message\' => $queryText,                         \'status\' => \'Open\',                         \'priority\' => \'Medium\',                         \'category\' => \'General\',                         \'intent\' => \'EMERGENCY: \' . $reason,                         \'confidence\' => 0.0,                         \'created_at\' => now(),                         \'updated_at\' => now(),                     ]);                 },                 \'db_insert\' => function() use ($ticketNo, $employeeNum, $queryText, $reason) {                     return DB::table(\'hr_inboxes\')->insert([                         \'ticket_no\' => $ticketNo,                         \'from_user\' => $employeeNum ?: \'GUEST\',                         \'message\' => $queryText,                         \'status\' => \'Open\',                         \'priority\' => \'Medium\',                         \'category\' => \'General\',                         \'intent\' => \'EMERGENCY: \' . $reason,                         \'confidence\' => 0.0,                         \'created_at\' => now(),                         \'updated_at\' => now(),                     ]);                 },                 \'raw_sql\' => function() use ($ticketNo, $employeeNum, $queryText, $reason) {                     $sql = "INSERT INTO hr_inboxes (ticket_no, from_user, message, status, priority, category, intent, confidence, created_at, updated_at)                              VALUES (?, ?, ?, \'Open\', \'Medium\', \'General\', ?, 0.0, NOW(), NOW())";                     return DB::insert($sql, [$ticketNo, $employeeNum ?: \'GUEST\', $queryText, \'EMERGENCY: \' . $reason]);                 }             ];              foreach ($methods as $methodName => $method) {                 try {                     $result = $method();                     if ($result) {                         Log::info("âœ… Emergency ticket created via {$methodName}", [\'ticket_no\' => $ticketNo]);                                                  // Also create query record if possible                         try {                             Query::create([                                 \'queryID\' => Str::uuid(),                                 \'employeeNum\' => $employeeNum,                                 \'question\' => $queryText,                                 \'response\' => \'EMERGENCY Escalated to HR - \' . $ticketNo,                                 \'confidenceScore\' => 0.0,                                 \'queryType\' => \'Escalated\',                                 \'questionTime\' => now(),                                 \'responseTime\' => now(),                                 \'isEscalated\' => true,                                 \'handledBy\' => \'HR\',                             ]);                         } catch (\\Exception $e) {                             // Ignore query creation errors in emergency mode                         }                                                  return $ticketNo;                     }                 } catch (\\Exception $e) {                     Log::warning("Emergency method {$methodName} failed: " . $e->getMessage());                     continue;                 }             }              // ðŸ†• FINAL FALLBACK: Log to file if database is completely down             $this->logTicketToFile($ticketNo, $employeeNum, $queryText, $reason);             return $ticketNo;          } catch (\\Exception $e) {             Log::error(\'ðŸš¨ CRITICAL: All ticket creation methods failed: \' . $e->getMessage());                          // Ultimate fallback - log to file and return ticket number anyway             $this->logTicketToFile($ticketNo, $employeeNum, $queryText, $reason);             return $ticketNo;         }     }      /**      * ðŸ†• NEW: Log ticket to file as final emergency backup      */     private function logTicketToFile(string $ticketNo, $employeeNum, string $queryText, string $reason): void     {         try {             $logEntry = [                 \'timestamp\' => now()->toISOString(),                 \'ticket_no\' => $ticketNo,                 \'employeeNum\' => $employeeNum,                 \'query\' => $queryText,                 \'reason\' => $reason,                 \'emergency\' => true             ];              $logPath = storage_path(\'logs/emergency_tickets.log\');             file_put_contents($logPath, json_encode($logEntry) . PHP_EOL, FILE_APPEND | LOCK_EX);                          Log::warning("ðŸš¨ Ticket logged to emergency file: {$ticketNo}");                      } catch (\\Exception $e) {             // If even file logging fails, there\'s nothing more we can do             Log::error(\'ðŸš¨ CRITICAL: Emergency file logging failed: \' . $e->getMessage());         }     } }', 'Resolved', 1, 'medium', '2025-10-27 16:35:51', NULL, NULL, NULL, NULL, 0, '2025-11-05 05:33:21', 'General', 'EMERGENCY: User requested human assistance', 0),
	(58, 'TKT-8ZQPTPG7-1761612408', 'EMP001', '<?php  namespace App\\Http\\Controllers;  use Illuminate\\Http\\Request; use App\\Models\\Query; use App\\Models\\HrInbox; use App\\Models\\GuidedQuestion; use Illuminate\\Support\\Str; use App\\Services\\DialogflowService; use Illuminate\\Support\\Facades\\Auth; use Illuminate\\Support\\Facades\\Log; use Illuminate\\Support\\Facades\\Session; use Illuminate\\Support\\Facades\\DB;  class DialogflowController extends Controller {     private $maxRetries = 3;      public function webhook(Request $request)     {         try {             Log::info(\'ðŸ” Dialogflow Webhook Called\', [\'input\' => $request->all()]);              // ðŸ†• FIXED: Handle multiple input formats             $queryText = $this->extractQueryText($request);             $employeeNum = Auth::check() ? Auth::user()->employeeNum : 0;              if (empty($queryText)) {                 Log::warning(\'Empty query text received\');                 return response()->json([                     \'status\' => \'success\',                     \'fulfillmentText\' => "I didn\'t receive your message. Could you please try again?"                 ]);             }              Log::info(\'Processing query:\', [\'query\' => $queryText, \'employee\' => $employeeNum]);              // ðŸ†• NEW: Check if this is a retry after multiple failed attempts             $retryResponse = $this->handleRetryScenario($queryText, $employeeNum);             if ($retryResponse) {                 return $retryResponse;             }              // ðŸ’¬ Handle greetings - start guided flow immediately             if ($this->isGreeting($queryText)) {                 Log::info(\'Greeting detected, starting guided flow\');                 // ðŸ†• Reset retry counter for new conversation                 $this->resetRetryCount();                 return response()->json([                     \'status\' => \'guided_flow\',                     \'fulfillmentText\' => "ðŸ‘‹ Hello! I\'m here to help with HR questions. Let me guide you to the right information.",                     \'guided_flow\' => true                 ]);             }              // ðŸ”¥ IMPROVED: Handle explicit escalation requests             if ($this->isEscalationRequest($queryText)) {                 Log::info(\'Escalation request detected\', [\'query\' => $queryText]);                 $this->resetRetryCount();                 return $this->escalateToHR($queryText, $employeeNum, \'User requested human assistance\');             }              // ðŸ’¬ Handle simple conversational responses             $conversationalResponse = $this->handleConversationalQueries($queryText);             if ($conversationalResponse) {                 $this->resetRetryCount();                 return $conversationalResponse;             }              // ðŸŽ¯ Try Dialogflow for direct questions             $sessionId = session()->getId() ?? Str::random(10);             $dialogflow = new DialogflowService();                          Log::info(\'Calling Dialogflow service\', [\'sessionId\' => $sessionId]);             $result = $dialogflow->detectIntent($queryText, $sessionId);             $dialogflow->close();              $confidence = $result->getIntentDetectionConfidence() ?? 0.0;             $fulfillmentText = $result->getFulfillmentText() ?? "I want to make sure I give you accurate information. Let me guide you through our topics.";             $intentName = $result->getIntent() ? $result->getIntent()->getDisplayName() : \'Default Fallback Intent\';              Log::info(\'Dialogflow Response\', [                 \'confidence\' => $confidence,                 \'intent\' => $intentName,                 \'fulfillmentText\' => $fulfillmentText             ]);              // ðŸ†• NEW: Check if this is HR-related but bot can\'t answer properly             $isHRRelated = $this->isHRRelatedQuestion($queryText);             $cantAnswer = $this->cantAnswerQuestion($confidence, $intentName, $fulfillmentText);              if ($isHRRelated && $cantAnswer) {                 Log::info(\'HR-related question detected but bot cannot answer\', [                     \'confidence\' => $confidence,                     \'intent\' => $intentName                 ]);                 return $this->suggestHREscalation($queryText, $employeeNum, "HR-related question with low confidence");             }              // ðŸ”¥ IMPROVED: Auto-escalate based on multiple factors             if ($this->shouldEscalate($queryText, $confidence, $intentName)) {                 Log::info(\'Auto-escalating query\', [                     \'reason\' => \'Low confidence or urgent content\',                     \'confidence\' => $confidence,                     \'intent\' => $intentName                 ]);                 $this->resetRetryCount();                 return $this->escalateToHR($queryText, $employeeNum, "Auto-escalated: Confidence {$confidence}, Intent: {$intentName}");             }              // ðŸ†• NEW: Handle retry logic for unclear questions             if ($this->shouldRetry($confidence, $intentName)) {                 $retryCount = $this->incrementRetryCount();                 Log::info(\'Low confidence response, prompting retry\', [                     \'retryCount\' => $retryCount,                     \'confidence\' => $confidence                 ]);                  if ($retryCount >= $this->maxRetries) {                     return $this->offerHREscalation($queryText, $employeeNum);                 }                  return response()->json([                     \'status\' => \'retry\',                     \'fulfillmentText\' => $this->getRetryMessage($retryCount),                     \'retryCount\' => $retryCount,                     \'needs_clarification\' => true                 ]);             }              // ðŸ¤– If reasonable confidence, return direct answer             if ($confidence > 0.6 || $intentName !== \'Default Fallback Intent\') {                 Log::info(\'Returning direct answer\', [\'confidence\' => $confidence, \'intent\' => $intentName]);                 $this->resetRetryCount();                  Query::create([                     \'queryID\' => Str::uuid(),                     \'employeeNum\' => $employeeNum,                     \'question\' => $queryText,                     \'response\' => $fulfillmentText,                     \'confidenceScore\' => $confidence,                     \'queryType\' => \'Dialogflow\',                     \'questionTime\' => now(),                     \'responseTime\' => now(),                     \'isEscalated\' => false,                     \'handledBy\' => \'Bot\',                 ]);                  return response()->json([                     \'status\' => \'success\',                     \'fulfillmentText\' => $fulfillmentText,                     \'confidence\' => $confidence,                     \'intent\' => $intentName                 ]);             }              // ðŸ”„ Low confidence - start guided flow             Log::info(\'Low confidence, starting guided flow\', [\'confidence\' => $confidence]);             $this->resetRetryCount();             return response()->json([                 \'status\' => \'guided_flow\',                 \'fulfillmentText\' => "I want to make sure I give you the right information. Let me guide you through our HR topics.",                 \'guided_flow\' => true             ]);          } catch (\\Throwable $e) {             Log::error(\'âŒ Dialogflow error: \' . $e->getMessage(), [                 \'trace\' => $e->getTraceAsString(),                 \'request\' => $request->all()             ]);              // ðŸ†• FIXED: Better error response that doesn\'t break the frontend             return response()->json([                 \'status\' => \'success\', // Use success to prevent frontend errors                 \'fulfillmentText\' => "I\'m having trouble processing your request right now. Let me guide you through our HR topics instead.",                 \'fallback\' => true             ]);         }     }      /**      * ðŸ†• NEW: Check if question is HR-related      */     private function isHRRelatedQuestion(string $queryText): bool     {         $hrKeywords = [             // Employment             \'hire\', \'hiring\', \'recruitment\', \'recruit\', \'job\', \'position\', \'role\',             \'interview\', \'application\', \'resume\', \'cv\', \'candidate\',             \'onboarding\', \'orientation\', \'probation\', \'contract\',                          // Compensation & Benefits             \'salary\', \'pay\', \'wage\', \'compensation\', \'benefit\', \'insurance\',             \'health insurance\', \'dental\', \'vision\', \'retirement\', \'pension\',             \'401k\', \'bonus\', \'commission\', \'raise\', \'increase\', \'promotion\',                          // Time Off             \'vacation\', \'holiday\', \'leave\', \'sick\', \'time off\', \'pto\',             \'personal day\', \'maternity\', \'paternity\', \'fmla\',                          // Policies             \'policy\', \'procedure\', \'handbook\', \'rule\', \'regulation\',             \'code of conduct\', \'dress code\', \'attendance\', \'punctuality\',                          // Performance             \'performance\', \'review\', \'appraisal\', \'evaluation\', \'kpi\',             \'goal\', \'objective\', \'feedback\', \'development\', \'training\',                          // Employee Relations             \'grievance\', \'complaint\', \'concern\', \'issue\', \'problem\',             \'dispute\', \'conflict\', \'mediation\', \'disciplinary\', \'warning\',                          // Workplace             \'workplace\', \'environment\', \'safety\', \'harassment\', \'discrimination\',             \'diversity\', \'inclusion\', \'accommodation\', \'remote\', \'hybrid\',                          // Separation             \'termination\', \'fired\', \'dismissal\', \'resignation\', \'quit\',             \'exit\', \'severance\', \'layoff\', \'redundancy\'         ];          foreach ($hrKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Check if bot cannot answer the question properly      */     private function cantAnswerQuestion(float $confidence, string $intentName, string $fulfillmentText): bool     {         // Low confidence         if ($confidence < 0.4) {             return true;         }          // Default fallback intent         if ($intentName === \'Default Fallback Intent\') {             return true;         }          // Generic or unclear responses         $unclearResponses = [             \'i didn\\\'t understand\',             \'can you rephrase\',             \'could you clarify\',             \'i\\\'m not sure\',             \'can you try asking\',             \'please rephrase\',             \'not clear\'         ];          foreach ($unclearResponses as $unclear) {             if (stripos($fulfillmentText, $unclear) !== false) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Suggest HR escalation for HR-related questions bot can\'t answer      */     private function suggestHREscalation(string $queryText, $employeeNum, string $reason): \\Illuminate\\Http\\JsonResponse     {         Log::info(\'Suggesting HR escalation\', [\'reason\' => $reason]);          return response()->json([             \'status\' => \'suggest_escalation\',             \'fulfillmentText\' => "I understand this is an HR-related question, but I want to make sure you get the most accurate information. Would you like me to escalate this to our HR team for proper assistance?",             \'suggest_hr\' => true,             \'pending_escalation\' => [                 \'query\' => $queryText,                 \'employeeNum\' => $employeeNum,                 \'reason\' => $reason             ],             \'options\' => [                 [\'text\' => \'âœ… Yes, please escalate to HR\', \'action\' => \'escalate\'],                 [\'text\' => \'ðŸ”„ No, let me rephrase my question\', \'action\' => \'rephrase\']             ]         ]);     }      /**      * ðŸ†• NEW: Handle retry scenario (when user responds to retry prompt)      */     private function handleRetryScenario(string $queryText, $employeeNum): ?\\Illuminate\\Http\\JsonResponse     {         $retryCount = Session::get(\'retry_count\', 0);                  if ($retryCount > 0) {             // Check if user wants to escalate             if ($this->wantsEscalation($queryText)) {                 $this->resetRetryCount();                 return $this->escalateToHR($queryText, $employeeNum, "User chose escalation after {$retryCount} retries");             }              // Check if user wants to rephrase             if ($this->wantsToRephrase($queryText)) {                 $this->resetRetryCount();                 return response()->json([                     \'status\' => \'retry_reset\',                     \'fulfillmentText\' => "Okay, please ask your question in a different way and I\'ll do my best to help!"                 ]);             }         }          return null;     }      /**      * ðŸ†• NEW: Check if user wants escalation      */     private function wantsEscalation(string $queryText): bool     {         $escalationPatterns = [             \'/\\b(yes|yeah|sure|okay|please|escalate|hr)\\b/i\',             \'/\\bgo ahead\\b/i\',             \'/\\bcontact hr\\b/i\',             \'/\\bsend to hr\\b/i\',             \'/\\bhuman help\\b/i\'         ];          foreach ($escalationPatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Check if user wants to rephrase      */     private function wantsToRephrase(string $queryText): bool     {         $rephrasePatterns = [             \'/\\b(no|nope|nevermind)\\b/i\',             \'/\\brephrase\\b/i\',             \'/\\bdifferent\\b/i\',             \'/\\btry again\\b/i\',             \'/\\bnew question\\b/i\',             \'/\\bstart over\\b/i\'         ];          foreach ($rephrasePatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Check if we should retry (low confidence responses)      */     private function shouldRetry(float $confidence, string $intentName): bool     {         if ($confidence < 0.5) {             return true;         }          if ($intentName === \'Default Fallback Intent\') {             return true;         }          return false;     }      /**      * ðŸ†• NEW: Get appropriate retry message based on retry count      */     private function getRetryMessage(int $retryCount): string     {         $messages = [             1 => "I\'m not sure I understand. Could you please rephrase your question?",             2 => "I\'m still having trouble understanding. Could you try asking in a different way?",             3 => "I want to make sure I help you properly. Could you provide more details or context?"         ];          return $messages[$retryCount] ?? $messages[1];     }      /**      * ðŸ†• NEW: Offer HR escalation after max retries      */     private function offerHREscalation(string $queryText, $employeeNum): \\Illuminate\\Http\\JsonResponse     {         Log::info(\'Offering HR escalation after max retries\');          return response()->json([             \'status\' => \'offer_escalation\',             \'fulfillmentText\' => "I\'m having difficulty understanding your question after several attempts. Would you like me to escalate this to our HR team who can provide better assistance?",             \'max_retries_reached\' => true,             \'pending_escalation\' => [                 \'query\' => $queryText,                 \'employeeNum\' => $employeeNum,                 \'reason\' => \'Max retries reached\'             ],             \'options\' => [                 [\'text\' => \'âœ… Yes, please connect me with HR\', \'action\' => \'escalate\'],                 [\'text\' => \'ðŸ”„ Let me try asking differently\', \'action\' => \'rephrase\'],                 [\'text\' => \'âŒ Cancel and start over\', \'action\' => \'cancel\']             ]         ]);     }      /**      * ðŸ†• NEW: Increment retry count      */     private function incrementRetryCount(): int     {         $count = Session::get(\'retry_count\', 0) + 1;         Session::put(\'retry_count\', $count);         Session::put(\'last_retry_time\', now());         return $count;     }      /**      * ðŸ†• NEW: Reset retry count      */     private function resetRetryCount(): void     {         Session::forget(\'retry_count\');         Session::forget(\'last_retry_time\');     }      /**      * ðŸ†• FIXED: Extract query text from multiple possible input formats      */     private function extractQueryText(Request $request): string     {         // Format 1: Direct message parameter (from our frontend)         if ($request->has(\'message\')) {             return trim($request->input(\'message\'));         }          // Format 2: Dialogflow webhook format         if ($request->has(\'queryResult.queryText\')) {             return trim($request->input(\'queryResult.queryText\'));         }          // Format 3: Alternative Dialogflow format         if ($request->has(\'queryResult.parameters.message\')) {             return trim($request->input(\'queryResult.parameters.message\'));         }          // Format 4: Raw text in request         $text = $request->input(\'text\') ?? $request->input(\'query\') ?? \'\';         return trim($text);     }      /**      * ðŸ†• IMPROVED: Better greeting detection      */     private function isGreeting(string $queryText): bool     {         $greetingPatterns = [             \'/^(hi|hello|hey|greetings|good morning|good afternoon|good evening)[\\s\\.,!]*$/i\',             \'/^start$/i\',             \'/^help$/i\',             \'/^\\?$/\',             \'/^hello there$/i\',             \'/^hi there$/i\'         ];          foreach ($greetingPatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ”¥ IMPROVED: Better detection for escalation requests      */     private function isEscalationRequest(string $queryText): bool     {         $escalationPatterns = [             \'/\\b(escalate|human|real person|live agent|representative|manager)\\b/i\',             \'/\\btalk to (hr|human|person|someone|agent|manager)\\b/i\',             \'/\\bspeak with (hr|human|person|someone|agent|manager)\\b/i\',             \'/\\bconnect with (hr|human|person|someone|agent)\\b/i\',             \'/\\bI want to talk to\\b/i\',             \'/\\bI need to speak with\\b/i\',             \'/\\bcan I speak with\\b/i\',             \'/\\bcontact hr\\b/i\',             \'/\\bget me hr\\b/i\',             \'/\\bnot a bot\\b/i\',             \'/\\bnot chatbot\\b/i\',             \'/\\breal human\\b/i\',             \'/\\blive person\\b/i\',             \'/\\bhuman help\\b/i\'         ];          foreach ($escalationPatterns as $pattern) {             if (preg_match($pattern, $queryText)) {                 return true;             }         }          return false;     }      /**      * ðŸ†• NEW: Handle simple conversational queries without Dialogflow      */     private function handleConversationalQueries(string $queryText): ?\\Illuminate\\Http\\JsonResponse     {         $conversationalMap = [             \'thanks\' => ["You\'re very welcome! ðŸ˜Š Is there anything else I can help you with?", "Happy to help! Let me know if you need anything else."],             \'thank you\' => ["You\'re very welcome! ðŸ˜Š Is there anything else I can help you with?", "My pleasure! Feel free to ask if you have more questions."],             \'bye\' => ["ðŸ‘‹ Goodbye! Feel free to ask if you have more HR questions.", "Have a great day! ðŸ‘‹"],             \'goodbye\' => ["ðŸ‘‹ Goodbye! Feel free to ask if you have more HR questions.", "Take care! ðŸ‘‹"],             \'how are you\' => ["I\'m doing great, thanks for asking! Ready to help with your HR questions. ðŸ˜Š", "I\'m functioning well! How can I assist you with HR matters today?"],             \'who are you\' => ["I\'m Aihra, your AI HR Assistant! I\'m here to help with HR questions and guide you to the right information. ðŸ¤–", "I\'m Aihra, an AI assistant specialized in HR topics. How can I help you today?"],         ];          foreach ($conversationalMap as $pattern => $responses) {             if (stripos($queryText, $pattern) !== false) {                 $response = $responses[array_rand($responses)];                 return response()->json([                     \'status\' => \'success\',                     \'fulfillmentText\' => $response                 ]);             }         }          return null;     }      /**      * ðŸ”¥ IMPROVED: Better escalation logic      */     private function shouldEscalate(string $queryText, float $confidence, string $intentName): bool     {         // Always escalate if it\'s the default fallback intent with low confidence         if ($intentName === \'Default Fallback Intent\' && $confidence < 0.4) {             return true;         }          // Escalate if confidence is very low         if ($confidence < 0.3) {             return true;         }          // Escalate for urgent/emotional keywords         $urgentKeywords = [             \'urgent\', \'emergency\', \'complaint\', \'issue\', \'problem\', \'error\',             \'not working\', \'help me\', \'now\', \'asap\', \'immediately\', \'right now\',             \'serious\', \'critical\', \'angry\', \'frustrated\', \'disappointed\', \'upset\',             \'unhappy\', \'wrong\', \'broken\', \'fix\', \'resolve\', \'complaint\',             \'harassment\', \'discrimination\', \'bullying\', \'unsafe\', \'danger\'         ];          foreach ($urgentKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return true;             }         }          // Escalate complex personal issues         $personalIssues = [             \'salary\', \'pay\', \'raise\', \'promotion\', \'disciplinary\', \'warning\',             \'termination\', \'fired\', \'resign\', \'quit\', \'legal\', \'lawyer\',             \'contract\', \'agreement\', \'confidential\', \'private\', \'personal\'         ];          $personalCount = 0;         foreach ($personalIssues as $issue) {             if (stripos($queryText, $issue) !== false) {                 $personalCount++;             }         }          // If multiple personal issues mentioned, escalate         if ($personalCount >= 2) {             return true;         }          return false;     }      /**      * ðŸ”¥ FIXED: Escalate query to HR inbox - ALWAYS creates real ticket      */     private function escalateToHR(string $queryText, $employeeNum, string $reason = \'User requested\'): \\Illuminate\\Http\\JsonResponse     {         $ticketNo = null;                  try {             Log::info("ðŸŽ¯ Starting escalation process...", [                 \'reason\' => $reason,                 \'employee\' => $employeeNum,                 \'query\' => substr($queryText, 0, 100)             ]);              // Generate unique ticket number FIRST             $ticketNo = \'TKT-\' . strtoupper(Str::random(8)) . \'-\' . time();             Log::info("ðŸŽ¯ Generated ticket: " . $ticketNo);              // Determine priority based on content             $priority = $this->determinePriority($queryText);             $category = $this->determineCategory($queryText);              // ðŸ†• CRITICAL FIX: Create HR inbox ticket with multiple fallback attempts             $inbox = null;             $maxAttempts = 3;                          for ($attempt = 1; $attempt <= $maxAttempts; $attempt++) {                 try {                     $inbox = HrInbox::create([                         \'ticket_no\' => $ticketNo,                         \'from_user\' => $employeeNum ?: \'GUEST\',                         \'message\' => $queryText,                         \'status\' => \'Open\',                         \'priority\' => $priority,                         \'category\' => $category,                         \'intent\' => \'Escalated from Chatbot: \' . $reason,                         \'confidence\' => 0.0,                         \'created_at\' => now(),                         \'updated_at\' => now(),                     ]);                     Log::info("âœ… HR Inbox created successfully on attempt {$attempt}", [\'ticket_no\' => $ticketNo]);                     break; // Success, break out of retry loop                                      } catch (\\Exception $createError) {                     Log::warning("âŒ HR Inbox creation failed on attempt {$attempt}: " . $createError->getMessage());                                          if ($attempt === $maxAttempts) {                         // Last attempt failed, try alternative creation method                         $inbox = $this->createTicketAlternativeMethod($ticketNo, $employeeNum, $queryText, $priority, $category, $reason);                         if ($inbox) {                             Log::info("âœ… HR Inbox created via alternative method", [\'ticket_no\' => $ticketNo]);                             break;                         }                         throw new \\Exception("Failed to create HR ticket after {$maxAttempts} attempts: " . $createError->getMessage());                     }                                          // Wait briefly before retry                     usleep(500000); // 0.5 seconds                 }             }              // Create query record with proper error handling             try {                 Query::create([                     \'queryID\' => Str::uuid(),                     \'employeeNum\' => $employeeNum,                     \'question\' => $queryText,                     \'response\' => \'Escalated to HR - \' . $ticketNo,                     \'confidenceScore\' => 0.0,                     \'queryType\' => \'Escalated\',                     \'questionTime\' => now(),                     \'responseTime\' => now(),                     \'isEscalated\' => true,                     \'handledBy\' => \'HR\',                 ]);                 Log::info("âœ… Query record created successfully");             } catch (\\Exception $queryError) {                 Log::warning(\'Query record creation failed, but HR ticket was created\', [                     \'error\' => $queryError->getMessage(),                     \'ticket_no\' => $ticketNo                 ]);                 // Continue even if query record fails - the main ticket is what matters             }              Log::info("âœ… Escalation completed successfully", [\'ticket_no\' => $ticketNo]);              return response()->json([                 \'status\' => \'escalated\',                 \'fulfillmentText\' => "âœ… I\'ve escalated your query to our HR team. They\'ll get back to you soon. Your ticket number is: **{$ticketNo}**",                 \'ticket_no\' => $ticketNo,                 \'escalated\' => true,                 \'priority\' => $priority             ]);          } catch (\\Exception $e) {             Log::error(\'âŒ Escalation failed: \' . $e->getMessage(), [                 \'trace\' => $e->getTraceAsString(),                 \'query\' => $queryText             ]);              // ðŸ†• CRITICAL FIX: ALWAYS create a ticket, even if basic methods fail             $finalTicketNo = $this->ensureTicketCreation($ticketNo, $employeeNum, $queryText, $reason);                          return response()->json([                 \'status\' => \'escalated\',                 \'fulfillmentText\' => "âœ… I\'ve created a support ticket for you. Our HR team will contact you soon. Your ticket number is: **{$finalTicketNo}**",                 \'ticket_no\' => $finalTicketNo,                 \'escalated\' => true,                 \'fallback_created\' => true             ]);         }     }      /**      * ðŸ†• NEW: Determine ticket priority based on content      */     private function determinePriority(string $queryText): string     {         $highPriorityKeywords = [             \'emergency\', \'urgent\', \'critical\', \'asap\', \'immediately\', \'now\',             \'harassment\', \'discrimination\', \'bullying\', \'unsafe\', \'danger\',             \'fired\', \'termination\', \'legal\', \'lawyer\', \'police\'         ];          $mediumPriorityKeywords = [             \'complaint\', \'issue\', \'problem\', \'error\', \'not working\', \'broken\',             \'salary\', \'pay\', \'raise\', \'promotion\', \'disciplinary\', \'warning\'         ];          foreach ($highPriorityKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return \'High\';             }         }          foreach ($mediumPriorityKeywords as $keyword) {             if (stripos($queryText, $keyword) !== false) {                 return \'Medium\';             }         }          return \'Low\';     }      /**      * ðŸ†• NEW: Determine ticket category based on content      */     private function determineCategory(string $queryText): string     {         $categories = [             \'Benefits\' => [\'benefit\', \'insurance\', \'health\', \'dental\', \'vacation\', \'time off\', \'leave\'],             \'Payroll\' => [\'salary\', \'pay\', \'paycheck\', \'wage\', \'bonus\', \'tax\'],             \'Employment\' => [\'hire\', \'hiring\', \'promotion\', \'raise\', \'position\', \'job\'],             \'Complaint\' => [\'complaint\', \'issue\', \'problem\', \'harassment\', \'discrimination\'],             \'Technical\' => [\'system\', \'login\', \'password\', \'access\', \'technical\', \'error\'],             \'Policy\' => [\'policy\', \'rule\', \'regulation\', \'procedure\', \'guideline\'],             \'General\' => [] // Default         ];          foreach ($categories as $category => $keywords) {             foreach ($keywords as $keyword) {                 if (stripos($queryText, $keyword) !== false) {                     return $category;                 }             }         }          return \'General\';     }      /**      * ðŸ†• NEW: Alternative ticket creation method using DB facade      */     private function createTicketAlternativeMethod(string $ticketNo, $employeeNum, string $queryText, string $priority, string $category, string $reason)     {         try {             Log::info("ðŸ”„ Trying alternative ticket creation method", [\'ticket_no\' => $ticketNo]);                          // Use DB facade for direct insertion             $now = now();             $result = DB::table(\'hr_inboxes\')->insert([                 \'ticket_no\' => $ticketNo,                 \'from_user\' => $employeeNum ?: \'GUEST\',                 \'message\' => $queryText,                 \'status\' => \'Open\',                 \'priority\' => $priority,                 \'category\' => $category,                 \'intent\' => \'Escalated from Chatbot: \' . $reason,                 \'confidence\' => 0.0,                 \'created_at\' => $now,                 \'updated_at\' => $now,             ]);              if ($result) {                 return DB::table(\'hr_inboxes\')->where(\'ticket_no\', $ticketNo)->first();             }                          return null;                      } catch (\\Exception $e) {             Log::error(\'Alternative ticket creation failed: \' . $e->getMessage());             return null;         }     }      /**      * ðŸ†• NEW: Ensure ticket creation no matter what - final fallback      */     private function ensureTicketCreation(?string $originalTicketNo, $employeeNum, string $queryText, string $reason): string     {         $ticketNo = $originalTicketNo ?: \'TKT-EMERGENCY-\' . time();                  try {             Log::info("ðŸš¨ EMERGENCY: Ensuring ticket creation with final fallback", [\'ticket_no\' => $ticketNo]);              // Try multiple creation methods             $methods = [                 \'eloquent_create\' => function() use ($ticketNo, $employeeNum, $queryText, $reason) {                     return HrInbox::create([                         \'ticket_no\' => $ticketNo,                         \'from_user\' => $employeeNum ?: \'GUEST\',                         \'message\' => $queryText,                         \'status\' => \'Open\',                         \'priority\' => \'Medium\',                         \'category\' => \'General\',                         \'intent\' => \'EMERGENCY: \' . $reason,                         \'confidence\' => 0.0,                         \'created_at\' => now(),                         \'updated_at\' => now(),                     ]);                 },                 \'db_insert\' => function() use ($ticketNo, $employeeNum, $queryText, $reason) {                     return DB::table(\'hr_inboxes\')->insert([                         \'ticket_no\' => $ticketNo,                         \'from_user\' => $employeeNum ?: \'GUEST\',                         \'message\' => $queryText,                         \'status\' => \'Open\',                         \'priority\' => \'Medium\',                         \'category\' => \'General\',                         \'intent\' => \'EMERGENCY: \' . $reason,                         \'confidence\' => 0.0,                         \'created_at\' => now(),                         \'updated_at\' => now(),                     ]);                 },                 \'raw_sql\' => function() use ($ticketNo, $employeeNum, $queryText, $reason) {                     $sql = "INSERT INTO hr_inboxes (ticket_no, from_user, message, status, priority, category, intent, confidence, created_at, updated_at)                              VALUES (?, ?, ?, \'Open\', \'Medium\', \'General\', ?, 0.0, NOW(), NOW())";                     return DB::insert($sql, [$ticketNo, $employeeNum ?: \'GUEST\', $queryText, \'EMERGENCY: \' . $reason]);                 }             ];              foreach ($methods as $methodName => $method) {                 try {                     $result = $method();                     if ($result) {                         Log::info("âœ… Emergency ticket created via {$methodName}", [\'ticket_no\' => $ticketNo]);                                                  // Also create query record if possible                         try {                             Query::create([                                 \'queryID\' => Str::uuid(),                                 \'employeeNum\' => $employeeNum,                                 \'question\' => $queryText,                                 \'response\' => \'EMERGENCY Escalated to HR - \' . $ticketNo,                                 \'confidenceScore\' => 0.0,                                 \'queryType\' => \'Escalated\',                                 \'questionTime\' => now(),                                 \'responseTime\' => now(),                                 \'isEscalated\' => true,                                 \'handledBy\' => \'HR\',                             ]);                         } catch (\\Exception $e) {                             // Ignore query creation errors in emergency mode                         }                                                  return $ticketNo;                     }                 } catch (\\Exception $e) {                     Log::warning("Emergency method {$methodName} failed: " . $e->getMessage());                     continue;                 }             }              // ðŸ†• FINAL FALLBACK: Log to file if database is completely down             $this->logTicketToFile($ticketNo, $employeeNum, $queryText, $reason);             return $ticketNo;          } catch (\\Exception $e) {             Log::error(\'ðŸš¨ CRITICAL: All ticket creation methods failed: \' . $e->getMessage());                          // Ultimate fallback - log to file and return ticket number anyway             $this->logTicketToFile($ticketNo, $employeeNum, $queryText, $reason);             return $ticketNo;         }     }      /**      * ðŸ†• NEW: Log ticket to file as final emergency backup      */     private function logTicketToFile(string $ticketNo, $employeeNum, string $queryText, string $reason): void     {         try {             $logEntry = [                 \'timestamp\' => now()->toISOString(),                 \'ticket_no\' => $ticketNo,                 \'employeeNum\' => $employeeNum,                 \'query\' => $queryText,                 \'reason\' => $reason,                 \'emergency\' => true             ];              $logPath = storage_path(\'logs/emergency_tickets.log\');             file_put_contents($logPath, json_encode($logEntry) . PHP_EOL, FILE_APPEND | LOCK_EX);                          Log::warning("ðŸš¨ Ticket logged to emergency file: {$ticketNo}");                      } catch (\\Exception $e) {             // If even file logging fails, there\'s nothing more we can do             Log::error(\'ðŸš¨ CRITICAL: Emergency file logging failed: \' . $e->getMessage());         }     } }', 'Resolved', 1, 'medium', '2025-10-27 16:46:49', NULL, NULL, NULL, NULL, 0, '2025-11-05 05:33:01', 'General', 'EMERGENCY: User requested human assistance', 0),
