INSERT INTO `queries` (`queryID`, `employeeNum`, `question`, `response`, `confidenceScore`, `queryType`, `questionTime`, `responseTime`, `isEscalated`, `handledBy`) VALUES
	('004430da-0fc2-48d9-8e2f-4c770e980ee5', 'EMP001', 'benefits', 'Employees are entitled to vacation and sick leave. Emergency leave may be granted for serious accidents, natural calamities, or urgent personal matters. Faculty and staff may also request leave without pay for up to one year for health, studies, or other valid reasons.', 0.613753, 'Dialogflow', '2025-12-02 04:33:04.000000', '2025-12-02 04:33:04.000000', 0, 'Bot'),
	('0082478c-5d70-494d-b364-75c03a520715', 'EMP001', 'credits', '"Leave credits vary: College faculty have 3 vacation and 3 sick leave credits, Basic Education teachers have 12 vacation and 12 sick leave credits, while office and general services staff have 15 vacation and 15 sick leave credits per year. Unused credits may be monetized."', 0.92629, 'Dialogflow', '2025-11-17 13:50:00.000000', '2025-11-17 13:50:00.000000', 0, 'Bot'),
	('01af0e7e-1ae6-480a-977b-7e3e10e13ae1', 'EMP001', 'What are the regular working hours?', 'Regular working hours are 8:00 AMâ€“12:00 NN and 1:00â€“5:00 PM, Monday to Saturday for non-teaching personnel. Faculty follow their teaching load schedules plus required consultation and institutional duties.', 0.77641, 'Dialogflow', '2025-12-01 02:02:04.000000', '2025-12-01 02:02:04.000000', 0, 'Bot'),
	('03460a2a-5007-424e-99c4-3a09dbbda787', 'EMP001', 'how do non-teaching personnel staff move up in rank?', 'Non-teaching staff move up in rank through a process defined in Policy No. 10, which mandates committee review and aims to reward professional growth and commitment to the institution’s values.', 0.621621, 'Dialogflow', '2025-12-13 11:17:36.493103', '2025-12-13 11:17:38.198145', 0, 'Bot'),
	('03a2d19d-c96c-49c0-8671-2820c5096c37', 'EMP001', 'What happens if Im late multiple times?', 'Employees must report on time and attend assigned duties. Attendance is monitored by immediate heads and the HR office, with semestral reports submitted. Tardiness and undertime may lead to salary deductions or disciplinary action.', 0.740117, 'Dialogflow', '2025-12-02 03:55:39.000000', '2025-12-02 03:55:39.000000', 0, 'Bot'),
